  font-family: var(--ring-font-family-monospace);
  font-size: var(--ring-font-size-smaller);
}

.ellipsis {
  overflow: hidden;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.resetButton {
  overflow: visible;

