  width: 20px;
  height: 20px;
  margin-left: calc(unit * 2);

  background-repeat: no-repeat;
  background-position: center;

  background-size: contain;
}

.highlight {
  color: var(--ring-link-hover-color);
}

.service {
  color: var(--ring-secondary-color);
}

.glyph {
  float: left;

  width: 20px;

  margin-right: unit;

  color: var(--ring-icon-secondary-color);
}

.avatar {
  composes: glyph;

  top: 0;

  height: 20px;

  object-fit: cover;
  object-position: center;
}

.rightGlyph {
  composes: glyph;

  float: right;

  margin-right: 0;
  margin-left: calc(unit * 2);
}

.checkboxContainer {
  position: absolute;
  top: 7px;
  left: 19px;

  width: 20px;
  height: 20px;
  margin-right: unit;
}

.compact .checkboxContainer {
