    top: 0;
    right: 0;
    bottom: 0;
    left: 0;

    border-radius: var(--ring-border-radius);

    &::before {
      background-image:
        linear-gradient(
          to right,
          var(--ring-main-color),
          var(--ring-button-loader-background) 40%,
          var(--ring-main-color) 80%
