  &:indeterminate:indeterminate + .cell .check {
    transition: none;

    opacity: 0;
  }

  &[disabled] ~ .label {
    color: var(--ring-disabled-color);
  }
}

.label {
  margin-left: unit;

  line-height: normal;
}
