  bottom: 0;

  width: 100%;
  height: calc(unit * 3);

  pointer-events: none;

  background: linear-gradient(to bottom, rgba(255, 255, 255, 0), var(--ring-content-background-color));
}

.disabled {
  pointer-events: none;

  color: var(--ring-disabled-color);
}
