@value unit from "../global/global.css";
@value listSpacing: unit;

.list {
  position: relative;

  z-index: 1;

  border-radius: var(--ring-border-radius);

  line-height: normal;
}

.simpleInner {
  overflow: auto;
}

.scrolling {
  pointer-events: none;
}

.separator {
  display: block;

  min-height: listSpacing;

  margin-top: listSpacing;
  padding: 0 calc(unit * 2) 1px;

  text-align: right;
  white-space: nowrap;

  color: var(--ring-secondary-color);
  border-top: 1px solid var(--ring-line-color);

  font-size: var(--ring-font-size-smaller);
  line-height: var(--ring-line-height-lower);
}

.separator_first {
  margin-top: 0;
  padding-top: 0;

  border: none;
}

.item {
  display: block;

  box-sizing: border-box;

  width: 100%;

  text-align: left;
  vertical-align: bottom;
  white-space: nowrap;
  text-decoration: none;

  outline: none;

  font-size: var(--ring-font-size);
}

.item.item {
  padding: 3px calc(unit * 2) 5px;

  line-height: calc(unit * 3);
}

.itemContainer {
  position: relative;
}

.compact {
  line-height: calc(unit * 2);
}

.error {
  cursor: default;

  /* Override ring-link */
  &,
  &:hover,
  &:focus,
  &:visited {
    color: var(--ring-error-color);
  }
}

.add {
  padding: unit calc(2 * unit);

  line-height: calc(4 * unit);
}

.top {
  display: flex;
  align-items: baseline;
  flex-direction: row;
}

.left {
  align-self: center;
  flex-shrink: 0;
}

.label {
  overflow: hidden;
  flex-grow: 1;
  flex-shrink: 1;

  text-align: left;
  white-space: nowrap;
  text-overflow: ellipsis;

  [dir="rtl"] & {
    text-align: right;
    direction: ltr;
  }
}

.description {
  overflow: hidden;
  flex-shrink: 100;

  padding-left: unit;

  text-align: right;
  white-space: nowrap;
  text-overflow: ellipsis;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
  font-weight: 400;
  line-height: var(--ring-line-height-lowest);
}

.right {
  display: flex;
  align-items: center;
  align-self: center;
  flex-direction: row;
  flex-shrink: 0;
}

.details {
  margin-bottom: 6px;

  white-space: normal;

