}

.loader {
  position: relative;
  z-index: 0;

  pointer-events: none;

  background-color: transparent;
}

.loaderBackground {
  position: absolute;
  z-index: -1;
  top: 1px;
  right: 1px;
  bottom: 1px;
  left: 1px;

  overflow: hidden;

  border-radius: var(--ring-border-radius-small);

  &::before {
    display: block;

    width: calc(100% + loaderWidth);
    height: 100%;

    content: "";
    animation: progress 1s linear infinite;

    background-image:
      linear-gradient(
        to right,
        var(--ring-content-background-color),
        var(--ring-selected-background-color) 40%,
        var(--ring-content-background-color) 80%
      );

    background-repeat: repeat;
    background-size: loaderWidth;
  }
}

.delayed .content::after {
  content: "…";
}

.short {
  width: calc(unit * 4);
  padding: 0;
}

.dropdownIcon {
  margin-right: -2px;

  margin-left: 2px;

  transition: color var(--ring-ease);

  color: var(--ring-icon-secondary-color);

  line-height: normal;
}

.button:hover .dropdownIcon {
  transition: none;

  color: var(--ring-main-color);
}

@keyframes progress {
  from {
    transform: translateX(calc(0 - loaderWidth));
  }

  to {
    transform: translateX(0);
  }
}

@keyframes text-loading {
  50% {
    opacity: 0.5;
