    text-align: right;
    direction: ltr;
  }
}

.title_first {
  margin-top: 0;
}

.text {
  letter-spacing: 1.5px;
  text-transform: uppercase;

  color: var(--ring-secondary-color);

  font-size: var(--ring-font-size-smaller);
}

.fade {
  position: absolute;
  bottom: 0;

  width: 100%;
  height: calc(unit * 3);

  pointer-events: none;

  background: linear-gradient(to bottom, rgba(255, 255, 255, 0), var(--ring-content-background-color));
}

.disabled {
